package com.glosso.server.tts

import java.math.BigDecimal
import java.time.Instant
import java.util.UUID

/**
 * Provider-agnostic TTS layer.
 *
 * The rest of Glosso (content generator, content pool, worker) talks to this
 * package only: it never imports a Cartesia or ElevenLabs type. Text goes out,
 * audio bytes plus metadata come back. See `docs/TTS-LAYER-BRIEF.md`.
 *
 * Privacy: only text generated by Glosso is ever sent to a provider. A learner's
 * recorded audio never leaves the device.
 */

/** The two audio variants Glosso ships: normal speed and slowed down. */
enum class TtsSpeed(val label: String, val defaultFactor: Double) {
    NORMAL("normal", 1.0),
    SLOW("slow", 0.7),
}

enum class AudioContainer(val extension: String, val mimeType: String) {
    MP3("mp3", "audio/mpeg"),
    OGG("ogg", "audio/ogg"),
    WAV("wav", "audio/wav"),
}

/**
 * Output format. Part of the cache fingerprint: the same text at a different
 * sample rate or bitrate is a different asset.
 */
data class AudioFormat(
    val container: AudioContainer = AudioContainer.MP3,
    val sampleRate: Int = 44_100,
    val bitRate: Int = 128_000,
) {
    val extension: String get() = container.extension
    val mimeType: String get() = container.mimeType

    /** Stable token used by the cache fingerprint. */
    fun token(): String = "${container.name.lowercase()}:$sampleRate:$bitRate"
}

/**
 * What the domain asks for. `provider` is intentionally absent: the router
 * decides who synthesizes. `voice` or `model` may be blank, in which case the
 * chosen provider's configured defaults apply.
 *
 * Voice policy: an explicit [voice] always wins. Otherwise, for a dialogue turn,
 * the content sets [speakerIndex] and the configured dialogue palette supplies a
 * distinct, stable voice per speaker. Otherwise the palette default is used. No
 * random assignment: the same content always resolves to the same voice.
 */
data class TtsRequest(
    val text: String,
    val language: String = "en",
    val voice: String = "",
    val model: String = "",
    val speed: TtsSpeed = TtsSpeed.NORMAL,
    val format: AudioFormat = AudioFormat(),
    /** 0-based speaker for dialogues; null for single-voice content. */
    val speakerIndex: Int? = null,
    /** Escape hatch for provider settings that are not first-class here. */
    val providerOptions: Map<String, String> = emptyMap(),
) {
    /** Same request for another dialogue speaker (deterministic voice). */
    fun asSpeaker(index: Int): TtsRequest = copy(speakerIndex = index)
}

/** A provider plus its request with model, voice and speed already resolved. */
data class TtsCandidate(
    val provider: TtsProvider,
    val request: TtsRequest,
    val speedFactor: Double,
)

/**
 * A provider's answer. Carries whatever the provider reported so the service can
 * validate, cache, cost and log it without knowing the vendor.
 */
data class TtsResult(
    val audio: ByteArray,
    val format: AudioFormat,
    val provider: String,
    val model: String,
    val voice: String,
    val speed: TtsSpeed,
    val speedFactor: Double,
    /** Duration if the provider reports it, else null. */
    val durationMs: Long?,
    val characters: Int,
    /** Provider credits/units if it reports them (ElevenLabs, etc.). */
    val credits: Double?,
    val estimatedCostUsd: BigDecimal,
    val metadata: Map<String, String> = emptyMap(),
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is TtsResult) return false
        return audio.contentEquals(other.audio) &&
            format == other.format &&
            provider == other.provider &&
            model == other.model &&
            voice == other.voice &&
            speed == other.speed &&
            speedFactor == other.speedFactor &&
            durationMs == other.durationMs &&
            characters == other.characters &&
            credits == other.credits &&
            estimatedCostUsd.compareTo(other.estimatedCostUsd) == 0 &&
            metadata == other.metadata
    }

    override fun hashCode(): Int {
        var result = audio.contentHashCode()
        result = 31 * result + format.hashCode()
        result = 31 * result + provider.hashCode()
        result = 31 * result + model.hashCode()
        result = 31 * result + voice.hashCode()
        result = 31 * result + speed.hashCode()
        result = 31 * result + speedFactor.hashCode()
        result = 31 * result + (durationMs?.hashCode() ?: 0)
        result = 31 * result + characters
        result = 31 * result + (credits?.hashCode() ?: 0)
        result = 31 * result + estimatedCostUsd.stripTrailingZeros().hashCode()
        result = 31 * result + metadata.hashCode()
        return result
    }
}

/**
 * Why a synthesis failed. Only genuinely transient failures (timeout, rate
 * limit, 5xx, connection) may be retried or fall back to another provider. An
 * invalid text or an unsupported language is a permanent content error: it is
 * surfaced immediately, never masked by a fallback.
 */
enum class TtsFailureKind(val isTransient: Boolean) {
    TIMEOUT(true),
    RATE_LIMITED(true),
    SERVER_ERROR(true),
    CONNECTION(true),

    INVALID_TEXT(false),
    UNSUPPORTED_LANGUAGE(false),
    UNSUPPORTED_VOICE(false),
    UNSUPPORTED_FORMAT(false),
    BAD_REQUEST(false),

    AUTHENTICATION(false),
    CONFIGURATION(false),
    AUDIO_INVALID(false),
    UNKNOWN(false),
}

class TtsException(
    val kind: TtsFailureKind,
    message: String,
    /** Seconds the provider asked us to wait, from `Retry-After`, if any. */
    val retryAfterSeconds: Long? = null,
    cause: Throwable? = null,
    /** The provider that produced the failure, when the router knows it. */
    val provider: String? = null,
) : RuntimeException(message, cause) {

    /** Same failure, tagged with the provider that raised it. */
    fun withProvider(id: String): TtsException =
        if (provider == id) this else TtsException(kind, message ?: kind.name, retryAfterSeconds, cause, id)
}

/** One unit of work. `jobId` is the correlation id used for observability. */
data class TtsJob(
    val jobId: String,
    val request: TtsRequest,
    val contentId: String? = null,
    val variantId: String? = null,
    val requestedAt: Instant = Instant.now(),
)

enum class TtsJobStatus { PUBLISHED, ALREADY_PUBLISHED, FAILED }

/** The outcome the worker records. Never carries secrets or audio bytes. */
data class TtsJobResult(
    val jobId: String,
    val status: TtsJobStatus,
    val asset: TtsAssetRecord? = null,
    val provider: String? = null,
    val model: String? = null,
    val voice: String? = null,
    val cacheHit: Boolean = false,
    val fallbackUsed: Boolean = false,
    val attempts: Int = 0,
    val requestDurationMs: Long = 0,
    val errorKind: TtsFailureKind? = null,
    val errorMessage: String? = null,
    val estimatedCostUsd: BigDecimal = BigDecimal.ZERO,
)

/** Metadata row. The binary lives in object storage; this is PostgreSQL only. */
data class TtsAssetRecord(
    val cacheKey: String,
    val contentId: String?,
    val text: String,
    val language: String,
    val provider: String,
    val model: String,
    val voice: String,
    /** The variant label, `normal` or `slow`. */
    val speed: String,
    val speedFactor: Double,
    /** Output format token, e.g. `mp3:44100:128000`. */
    val format: String,
    val objectKey: String,
    val durationMs: Long?,
    val sizeBytes: Long,
    val checksum: String,
    val estimatedCostUsd: BigDecimal,
    val characters: Int,
    val credits: Double?,
    val jobId: String?,
    val createdAt: Instant = Instant.now(),
    val id: String = UUID.randomUUID().toString(),
)

/** Append-only cost event: one per real generation, never per cache hit. */
data class TtsCostRecord(
    val jobId: String,
    val contentId: String?,
    val provider: String,
    val model: String,
    val voice: String,
    val characters: Int,
    val credits: Double?,
    val estimatedCostUsd: BigDecimal,
    val createdAt: Instant = Instant.now(),
)

data class R2Config(
    val endpoint: String,
    val bucket: String,
    val accessKey: String,
    val secretKey: String,
    val region: String = "auto",
    val pathStyle: Boolean = true,
) {
    /** Never expose the secret; use this for logs. */
    override fun toString(): String =
        "R2Config(endpoint=$endpoint, bucket=$bucket, region=$region, pathStyle=$pathStyle, credentials=***)"
}

/** Settings for one vendor. Secrets only ever come from the environment. */
data class ProviderConfig(
    val id: String,
    val apiKey: String?,
    val model: String,
    val defaultVoice: String,
    val baseUrl: String,
    val extra: Map<String, String> = emptyMap(),
) {
    val enabled: Boolean get() = !apiKey.isNullOrBlank()
}

/**
 * A small palette, not a voice per item. One default voice covers vocabulary
 * and drills; a short ordered list covers dialogue speakers so a dialogue
 * sounds like different people. Selection is deterministic (no randomness), so
 * regenerating the same content yields the same voice.
 *
 * Voice ids are configuration, never code: see `deploy/.env.example`.
 */
data class VoicePalette(
    val defaultVoice: String = "",
    val dialogueVoices: List<String> = emptyList(),
) {
    /** Resolves the voice for a speaker, or the default for single-voice content. */
    fun resolve(speakerIndex: Int?): String {
        if (speakerIndex == null || dialogueVoices.isEmpty()) return defaultVoice
        return dialogueVoices[Math.floorMod(speakerIndex, dialogueVoices.size)]
    }

    companion object {
        val EMPTY = VoicePalette()
    }
}

/**
 * All TTS configuration. Every value comes from the environment; nothing
 * production lives in code. See `deploy/.env.example`.
 */
data class TtsConfig(
    val provider: String,
    val fallbackProviders: List<String>,
    val maxConcurrency: Int,
    val maxRetries: Int,
    val timeoutSeconds: Long,
    val slowSpeedFactor: Double,
    val outputFormat: AudioFormat,
    val objectKeyPrefix: String,
    val cacheDir: String?,
    val r2: R2Config?,
    val cartesia: ProviderConfig,
    val elevenlabs: ProviderConfig,
    val pricing: Map<String, BigDecimal>,
    val voicePalette: VoicePalette = VoicePalette.EMPTY,
) {
    fun speedFactor(speed: TtsSpeed): Double = when (speed) {
        TtsSpeed.NORMAL -> 1.0
        TtsSpeed.SLOW -> slowSpeedFactor
    }

    fun provider(id: String): ProviderConfig = when (id.lowercase()) {
        CartesiaTtsProvider.ID -> cartesia
        ElevenLabsTtsProvider.ID -> elevenlabs
        else -> error("Unknown TTS provider '$id'")
    }

    companion object {
        const val DEFAULT_PROVIDER = CartesiaTtsProvider.ID

        fun fromEnv(env: Map<String, String> = System.getenv()): TtsConfig {
            fun value(key: String): String? = env[key]?.trim()?.takeIf { it.isNotEmpty() }
            fun int(key: String, default: Int) = value(key)?.toIntOrNull() ?: default
            fun long(key: String, default: Long) = value(key)?.toLongOrNull() ?: default
            fun double(key: String, default: Double) = value(key)?.toDoubleOrNull() ?: default

            val pricing = buildMap {
                for ((key, raw) in env) {
                    val prefix = "TTS_COST_PER_1M_CHARS_"
                    if (key.startsWith(prefix)) {
                        raw.trim().toBigDecimalOrNull()?.let {
                            put(key.removePrefix(prefix).lowercase(), it)
                        }
                    }
                }
            }

            val r2 = value("GLOSSO_R2_ENDPOINT")?.let { endpoint ->
                val bucket = value("GLOSSO_R2_BUCKET")
                val access = value("GLOSSO_R2_ACCESS_KEY")
                val secret = value("GLOSSO_R2_SECRET_KEY")
                if (bucket == null || access == null || secret == null) {
                    null
                } else {
                    R2Config(
                        endpoint = endpoint,
                        bucket = bucket,
                        accessKey = access,
                        secretKey = secret,
                        region = value("GLOSSO_R2_REGION") ?: "auto",
                        pathStyle = (value("GLOSSO_R2_PATH_STYLE") ?: "true").toBoolean(),
                    )
                }
            }

            val container = when (value("TTS_OUTPUT_FORMAT")?.lowercase()) {
                "ogg" -> AudioContainer.OGG
                "wav" -> AudioContainer.WAV
                else -> AudioContainer.MP3
            }

            // Cartesia auth: the API key is exchanged for a short-lived JWT at
            // /access-token, and only that JWT is sent to /tts/bytes.
            val cartesiaVersion = value("CARTESIA_VERSION") ?: CartesiaTtsProvider.DEFAULT_VERSION
            val cartesiaTokenVersion = value("CARTESIA_TOKEN_VERSION") ?: cartesiaVersion
            val cartesiaTokenGrants = value("CARTESIA_TOKEN_GRANTS") ?: CartesiaTtsProvider.DEFAULT_TOKEN_GRANTS
            val cartesiaTokenExpiresIn = value("CARTESIA_TOKEN_EXPIRES_IN")
                ?: CartesiaTtsProvider.DEFAULT_TOKEN_EXPIRES_SECONDS.toString()
            val cartesiaTokenRefreshSkew = value("CARTESIA_TOKEN_REFRESH_SKEW_SECONDS")
                ?: CartesiaTtsProvider.DEFAULT_TOKEN_REFRESH_SKEW_SECONDS.toString()

            return TtsConfig(
                provider = value("TTS_PROVIDER") ?: DEFAULT_PROVIDER,
                fallbackProviders = (value("TTS_FALLBACK_PROVIDERS") ?: "")
                    .split(',').map { it.trim().lowercase() }.filter { it.isNotEmpty() },
                maxConcurrency = int("TTS_MAX_CONCURRENCY", 2).coerceAtLeast(1),
                maxRetries = int("TTS_MAX_RETRIES", 2).coerceAtLeast(0),
                timeoutSeconds = long("TTS_TIMEOUT_SECONDS", 30).coerceAtLeast(1),
                slowSpeedFactor = double("TTS_SLOW_SPEED", TtsSpeed.SLOW.defaultFactor),
                outputFormat = AudioFormat(
                    container = container,
                    sampleRate = int("TTS_OUTPUT_SAMPLE_RATE", 44_100),
                    bitRate = int("TTS_OUTPUT_BIT_RATE", 128_000),
                ),
                objectKeyPrefix = value("TTS_CACHE_PREFIX") ?: "tts",
                cacheDir = value("GLOSSO_TTS_CACHE_DIR"),
                r2 = r2,
                cartesia = ProviderConfig(
                    id = CartesiaTtsProvider.ID,
                    apiKey = value("CARTESIA_API_KEY"),
                    model = value("CARTESIA_MODEL") ?: CartesiaTtsProvider.DEFAULT_MODEL,
                    defaultVoice = value("CARTESIA_DEFAULT_VOICE") ?: "",
                    baseUrl = value("CARTESIA_BASE_URL") ?: CartesiaTtsProvider.DEFAULT_BASE_URL,
                    extra = mapOf(
                        "version" to cartesiaVersion,
                        "tokenVersion" to cartesiaTokenVersion,
                        "tokenGrants" to cartesiaTokenGrants,
                        "tokenExpiresIn" to cartesiaTokenExpiresIn,
                        "tokenRefreshSkewSeconds" to cartesiaTokenRefreshSkew,
                    ),
                ),
                elevenlabs = ProviderConfig(
                    id = ElevenLabsTtsProvider.ID,
                    apiKey = value("ELEVENLABS_API_KEY"),
                    model = value("ELEVENLABS_MODEL") ?: ElevenLabsTtsProvider.DEFAULT_MODEL,
                    defaultVoice = value("ELEVENLABS_DEFAULT_VOICE") ?: "",
                    baseUrl = value("ELEVENLABS_BASE_URL") ?: ElevenLabsTtsProvider.DEFAULT_BASE_URL,
                ),
                pricing = pricing,
                voicePalette = VoicePalette(
                    defaultVoice = value("TTS_VOICE_DEFAULT") ?: "",
                    dialogueVoices = (value("TTS_DIALOGUE_VOICES") ?: "")
                        .split(',').map { it.trim() }.filter { it.isNotEmpty() },
                ),
            )
        }
    }
}
